perl -e '
open(my $fh, "<", "/tmp/copilot-tool-output-1782069905585-lf8f85.txt") or die $!;
my @lines;
while (<$fh>) {
    # Skip download/progress lines
    next if /Download/ || /Progress \(/;
    s/\r.*$//; # strip carriage returns
    push @lines, $_;
}
close($fh);

print "Total lines: " . scalar(@lines) . "\n";

my $in_summary = 0;
my $in_results = 0;
my $in_failures = 0;

print "\n=== REACTOR SUMMARY ===\n";
foreach my $line (@lines) {
    if ($line =~ /Reactor Summary/) { $in_summary = 1; }
    if ($in_summary) {
        print $line;
        if ($line =~ /---------/) { $in_summary = 0 if $in_summary > 1; $in_summary++ if $in_summary == 1; }
    }
}

print "\n=== RESULTS / FAILURES SUMMARY ===\n";
foreach my $line (@lines) {
    if ($line =~ /Results :/) { $in_results = 1; }
    if ($in_results) {
        print $line;
        if ($line =~ /Tests run:/) { $in_results = 0; }
    }
}

print "\n=== FAILED TESTS (ERROR/FAILURE LINES) ===\n";
my $err_count = 0;
foreach my $line (@lines) {
    if ($line =~ /\[ERROR\]/ && $line !~ /Failed to execute goal/ && $line !~ /To see the full stack trace/) {
        print $line;
        $err_count++;
        if ($err_count > 100) {
            print "... (truncated)\n";
            last;
        }
    }
}
'

