perl -e '
open(my $fh, "<", "/tmp/copilot-tool-output-1782069905585-lf8f85.txt") or die $!;
my $in_module = 0;
my @module_lines;
while (<$fh>) {
    next if /Download/ || /Progress \(/;
    s/\r.*$//;
    if (/Building Elide Data Store: Aggregation Data Store/) {
        $in_module = 1;
    }
    if ($in_module) {
        if (/Building Elide Data Store: In-Memory/) {
            $in_module = 0;
        }
        push @module_lines, $_;
    }
}
close($fh);

print "Aggregation Data Store lines: " . scalar(@module_lines) . "\n";

# Let us find any line with [ERROR] or <<< FAILURE! or <<< ERROR!
# Also print a few lines around it.
my $i = 0;
while ($i < scalar(@module_lines)) {
    my $line = $module_lines[$i];
    if ($line =~ /<<< FAILURE!/ || $line =~ /<<< ERROR!/ || $line =~ /\[ERROR\]   [a-zA-Z0-9_.-]+Test\./) {
        # print previous 2 lines and next 10 lines
        print "--------------------------------------------------\n";
        my $start = $i - 2 >= 0 ? $i - 2 : 0;
        my $end = $i + 15 < scalar(@module_lines) ? $i + 15 : scalar(@module_lines) - 1;
        for (my $j = $start; $j <= $end; $j++) {
            print "$j: $module_lines[$j]";
        }
        $i = $end; # skip ahead
    }
    $i++;
}
'

