const sql2 = 'SELECT PARSEDATETIME(FORMATDATETIME(x, \'yyyy-MM\'), \'yyyy-MM\') AS a, PARSEDATETIME(FORMATDATETIME(y, \'yyyy-MM\'), \'yyyy-MM\') AS b FROM test';
const sql3 = 'PARSEDATETIME(CONCAT(FORMATDATETIME(x, \'yyyy-\'), 3 * QUARTER(x) - 2), \'yyyy-MM\')';

const pat = /PARSEDATETIME\((.+?),\s*'yyyy-MM'\)/g;
const rep = 'PARSEDATETIME(CONCAT($1, \'-01\'), \'yyyy-MM-dd\')';

console.log(sql1.replace(pat, rep));
console.log(sql2.replace(pat, rep));
console.log(sql3.replace(pat, rep));
"

