    private static void closeSoftly(Connection conn) {
        try {
            if (conn != null) {
                conn.close();
            }
        } catch (SQLException e) {
            log.error("Exception encountered during close connection.", e);
        }
    }

    public static String rewriteQuery(String sql, SQLDialect dialect) {
        if (dialect != null && "H2".equalsIgnoreCase(dialect.getDialectType())) {
            sql = sql.replaceAll("PARSEDATETIME\\((.+?),\\s*'yyyy-MM'\\)", "PARSEDATETIME(CONCAT($1, '-01'), 'yyyy-MM-dd')");
        }
        return sql;
    }
}

