public static String rewriteQuery(String sql, SQLDialect dialect) {
    if (sql == null) {
        return null;
    }
    sql = sql.replaceAll(
            "PARSEDATETIME\\(\\s*FORMATDATETIME\\(([^)]+?),\\s*'yyyy-MM'\\),\\s*'yyyy-MM'\\)",
            "PARSEDATETIME(CONCAT(FORMATDATETIME($1, 'yyyy-MM'), '-01'), 'yyyy-MM-dd')");
    sql = sql.replaceAll(
            "PARSEDATETIME\\(\\s*CONCAT\\(\\s*FORMATDATETIME\\(([^)]+?),\\s*'yyyy-'\\),"
            + "\\s*3\\s*\\*\\s*QUARTER\\(([^)]+?)\\)\\s*-\\s*2\\s*\\),\\s*'yyyy-MM'\\)",
            "PARSEDATETIME(CONCAT(FORMATDATETIME($1, 'yyyy-'), 3 * QUARTER($2) - 2, '-01'), "
            + "'yyyy-MM-dd')");
    return sql;
}

