public class TestRegex {
    public static void main(String[] args) {
        String sql = "SELECT PARSEDATETIME(FORMATDATETIME(\"example_PlayerStats\".\"recordedDate\", 'yyyy-MM'), 'yyyy-MM') AS \"recordedDate\" FROM playerStats";

        String pattern = "PARSEDATETIME\\(\\s*FORMATDATETIME\\(([^)]+?),\\s*'yyyy-MM'\\),\\s*'yyyy-MM'\\)";
        String replacement = "PARSEDATETIME(CONCAT(FORMATDATETIME($1, 'yyyy-MM'), '-01'), 'yyyy-MM-dd')";

        System.out.println("SQL: " + sql);
        System.out.println("Result: " + sql.replaceAll(pattern, replacement));
        System.out.println("Matches: " + java.util.regex.Pattern.compile(pattern).matcher(sql).find());
    }
}

