public Month deserialize(Object val) {
    if (val instanceof java.time.Instant) {
        val = java.util.Date.from((java.time.Instant) val);
    } else if (val instanceof java.time.OffsetDateTime) {
        val = java.util.Date.from(((java.time.OffsetDateTime) val).toInstant());
    } else if (val instanceof java.time.ZonedDateTime) {
        val = java.util.Date.from(((java.time.ZonedDateTime) val).toInstant());
    } else if (val instanceof java.time.LocalDateTime) {
        val = java.util.Date.from(((java.time.LocalDateTime) val)
