    } else if (val instanceof java.time.LocalDate) {
        val = java.util.Date.from(((java.time.LocalDate) val)
                .atStartOfDay(java.time.ZoneId.systemDefault()).toInstant());
    }
    if (val instanceof Date) {
        return new Month((Date) val);
    }

