@Override
public Time deserialize(Object val) {
    final Object finalVal;
    if (val instanceof java.time.Instant) {
        finalVal = java.time.LocalDateTime.ofInstant((java.time.Instant) val,
                java.time.ZoneId.systemDefault());
    } else if (val instanceof java.time.OffsetDateTime) {
        finalVal = ((java.time.OffsetDateTime) val).toLocalDateTime();
    } else if (val instanceof java.time.ZonedDateTime) {
        finalVal = ((java.time.ZonedDateTime) val).toLocalDateTime();
    } else if (val instanceof java.time.LocalDateTime) {
        finalVal = val;
    } else if (val instanceof java.time.LocalDate) {
        finalVal = ((java.time.LocalDate) val).atStartOfDay();
    } else if (val instanceof Date) {
        finalVal = java.time.LocalDateTime.ofInstant(((Date) val).toInstant(),
                java.time.ZoneId.systemDefault());
    } else {
        finalVal = val;
    }

    if (finalVal instanceof LocalDateTime) {
        LocalDateTime localDateTime = (LocalDateTime) finalVal;
        return new Time(localDateTime,
                true, true, true, true, true, true,
                (time) -> localDateTime.toString());
    }
    try {
        TemporalAccessor parsed = formatter.parse(finalVal.toString());
        boolean supportsYear = true;
        boolean supportsMonth = parsed.isSupported(ChronoField.MONTH_OF_YEAR);
        boolean supportsDay = parsed.isSupported(ChronoField.DAY_OF_MONTH);
        boolean supportsHour = parsed.isSupported(ChronoField.HOUR_OF_DAY);
        boolean supportsMinute = parsed.isSupported(ChronoField.MINUTE_OF_HOUR);
        boolean supportsSecond = parsed.isSupported(ChronoField.SECOND_OF_MINUTE);

        return new Time(LocalDateTime.of(
                parsed.get(ChronoField.YEAR),
                supportsMonth ? parsed.get(ChronoField.MONTH_OF_YEAR) : 1,
                supportsDay ? parsed.get(ChronoField.DAY_OF_MONTH) : 1,
                supportsHour ? parsed.get(ChronoField.HOUR_OF_DAY) : 0,
                supportsMinute ? parsed.get(ChronoField.MINUTE_OF_HOUR) : 0,
                supportsSecond ? parsed.get(ChronoField.SECOND_OF_MINUTE) : 0),
                supportsYear,
                supportsMonth,
                supportsDay,
                supportsHour,
                supportsMinute,
                supportsSecond,
                (time) -> finalVal.toString());

